"""Cuaderno del estudiante, 1.º medio Lengua y Literatura, OA 04 (análisis de poemas).

Todos los poemas y versos son originales e inventados («de ejemplo»); cada ejercicio trae escrito el texto que necesita.
Nota: los títulos de las clases del repositorio ordenan el OA en siete pasos (hablante y propósito, actitud, lenguaje figurado,
repeticiones, símbolos y contexto, forma y significado, intertexto y revisión); este cuaderno los sigue y reparte entre ellos
los contenidos del OA oficial.
"""
from __future__ import annotations

from student_content_le_m1_a import E, L, MAT, arith

OA4 = "LE1M OA 04"

# Poemas originales de ejemplo (los versos se separan con « / »)
P1 = ("Todavía guardo tu silla junto a la ventana, / todavía riego el limonero que plantaste. / La tarde entra sin avisar, como siempre, / "
      "y se sienta en tu lugar, y no pregunta. / Todavía, todavía, repite el reloj. / Y yo le respondo: ya vendrás, ya vendrás.")
P2 = ("Pinté de azul las paredes de la casa nueva. / Colgué tu foto en el pasillo, no en el centro. / La tarde entra y la dejo pasar. / "
      "Aprendí que guardar no es detener: / el limonero también florece en otro patio.")
P3 = ("Cuando el viento toca el puerto / las barcas se ponen a hablar; / cada una cuenta un viaje cierto / y todas quieren zarpar.")
P5 = ("Contigo aprendí el nombre de las calles, / contigo supe qué es esperar un bus, / contigo el invierno fue un abrigo, / contigo, y sin ti, y otra vez contigo.")

# ------------------------------------------------------------------ OA 04 · clase 1
L(OA4, 1,
  "Aprenderé a leer un poema con propósito: reconocer al hablante lírico, el tema y el objeto que motiva el poema, y leerlo más de una vez en voz alta.",
  ["Distingo verso, estrofa y rima.", "Sé que la poesía expresa emociones y usa imágenes."],
  ["Un poema se lee distinto que un cuento: se lee más lento, se relee y se dice en voz alta para oír su ritmo. El propósito suele ser comprender qué siente o piensa la voz que habla y cómo lo expresa. Esa voz es el hablante lírico: un hablante creado por el poeta, que no siempre coincide con la persona real que escribió. Puede decir «yo», dirigirse a un «tú» o hablar de algo en general.",
   "El tema es la idea general del poema (la ausencia, la espera, el mar). El objeto lírico es aquello que despierta la emoción del hablante: una persona, un lugar, un recuerdo, un objeto. En el poema de la casa vacía, el hablante habla de una silla, de un limonero y de la tarde, pero el objeto lírico es la persona ausente a quien llama «tú». Distinguir tema y objeto lírico evita confundir de qué trata con qué lo provoca.",
   "Un buen lector hace tres lecturas. La primera, para oír el poema y captar la impresión general. La segunda, para identificar al hablante, al interlocutor (a quién se dirige) y el objeto lírico. La tercera, para fijarse en cómo lo dice: palabras repetidas, imágenes, orden de los versos. Cada lectura agrega una capa. No se espera una única respuesta, pero toda interpretación debe apoyarse en lo que el poema dice."],
  [("hablante lírico", "voz que expresa emociones o ideas en el poema; no es necesariamente el poeta"), ("objeto lírico", "aquello que despierta la emoción del hablante"), ("tema", "idea general de la que trata el poema"), ("interlocutor", "persona o cosa a quien el hablante se dirige")],
  [("Hablante y objeto lírico", f"Poema de ejemplo: «{P1}» ¿Quién habla y qué despierta su emoción?",
    ["Quien habla usa «yo» y se dirige a un «tú»: es el hablante lírico.", "Menciona la silla, el limonero y la tarde, pero todo remite a una persona que ya no está.", "El objeto lírico es la persona ausente."],
    "Habla un «yo» que se dirige a un «tú»; el objeto lírico es la persona ausente"),
   ("Tema y objeto lírico", f"Poema de ejemplo: «{P3}» ¿Cuál es el tema y qué mueve al hablante?",
    ["El poema describe barcas que hablan y quieren zarpar.", "El tema es el deseo de partir, de viajar.", "El objeto lírico son las barcas en el puerto."],
    "Tema: el deseo de partir; objeto lírico: las barcas en el puerto")],
  [("Creer que el hablante lírico es siempre el poeta.", "Se confunde la voz creada con la persona real.", "Pregunta quién habla en el poema, sin asumir que es el poeta."),
   ("Confundir tema con objeto lírico.", "Se mezcla la idea general con lo que despierta la emoción.", "Escribe el tema en pocas palabras y luego qué cosa, persona o recuerdo lo provoca.")],
  ([E("¿Qué es el hablante lírico? A) la voz que habla en el poema B) el poeta que lo escribió", "A) la voz que habla en el poema", "Es una voz creada, aunque puede parecerse al autor."),
    E("¿Para qué se lee un poema más de una vez? A) para captar más capas de sentido B) para memorizar sin entender", "A) para captar más capas de sentido", "Cada lectura permite descubrir algo nuevo."),
    E(f"Poema de ejemplo: «{P3}» ¿Cuántos versos tiene? Escribe el número.", "4", "Los versos se separan con barras: cuatro en total.")],
   [E(f"Poema de ejemplo: «{P1}» ¿A quién se dirige el hablante? A) a una persona ausente, el «tú» B) al limonero", "A) a una persona ausente, el «tú»", "Usa «tu silla» y «ya vendrás»: habla con alguien."),
    E(f"Poema de ejemplo: «{P2}» ¿Qué tema trata? A) seguir adelante después de una ausencia B) la compra de una casa", "A) seguir adelante después de una ausencia", "Pinta, cuelga una foto y aprende que guardar no es detener."),
    E(f"Poema de ejemplo: «{P3}» ¿Quiénes «hablan» en el poema? A) las barcas B) las personas del puerto", "A) las barcas", "El poema dice «las barcas se ponen a hablar».")],
   [E(f"Poema de ejemplo: «{P1}» ¿Qué objetos menciona el hablante para evocar a la persona ausente? A) la silla y el limonero B) el reloj y la tarde", "A) la silla y el limonero", "Son cosas ligadas a esa persona («tu silla», «el limonero que plantaste»); la tarde y el reloj son el tiempo."),
    E(f"Poema de ejemplo: «{P5}» ¿A quién se dirige el hablante? A) a un «tú» con quien compartió vida cotidiana B) a una calle", "A) a un «tú» con quien compartió vida cotidiana", "La repetición de «contigo» muestra la relación con otra persona."),
    E("Un lector dice: «El poema habla de una silla». Otra lectora dice: «El poema habla de la ausencia de alguien; la silla es lo que la recuerda». ¿Quién distingue mejor tema y objeto? A) la lectora B) el lector", "A) la lectora", "Separa la idea general (ausencia) de lo que la despierta (la silla).")],
   [E(f"Poema de ejemplo: «{P2}» Un lector dice: «El hablante es una persona que vive en Valparaíso». ¿Qué problema tiene? A) el poema no entrega ese dato; agrega información B) el poema no está dicho en primera persona", "A) el poema no entrega ese dato; agrega información", "El hablante lírico se interpreta solo con lo que dice el poema."),
    E("Después de una primera lectura en voz alta de «Cuando el viento toca el puerto…», una lectora dice: «Se siente animado y con ganas de partir». ¿Qué tipo de lectura es esa? A) la primera, de impresión general B) la tercera, de análisis formal", "A) la primera, de impresión general", "Capta la emoción general antes de analizar.")],
   [E(f"Poema de ejemplo: «{P1}» En la tercera lectura, ¿qué palabra con significado se repite más veces? Escribe la palabra.", "todavía", "Aparece en los versos primero y segundo, y dos veces en el quinto."),
    E(f"Poema de ejemplo: «{P2}» ¿Cuántas veces aparece la palabra «limonero»?", "1", "Solo aparece en el último verso del poema.")]),
  [E("Poema de ejemplo: «Hoy ordené mis cuadernos viejos. / En uno, tu letra me saludó desde un margen. / Cerré la tapa despacio, / como quien cuida un pájaro dormido». ¿Quién es el objeto lírico? A) la persona que escribió en el margen B) el pájaro", "A) la persona que escribió en el margen", "La emoción del hablante nace al encontrar la letra de alguien; el pájaro es solo una comparación.")],
  [E("¿Qué es un interlocutor en un poema? A) aquel a quien se dirige el hablante B) el título", "A) aquel a quien se dirige el hablante", "Es el «tú» de la voz poética."),
   E("¿Qué se hace en la segunda lectura de un poema? A) identificar hablante, interlocutor y objeto lírico B) solo leer el título", "A) identificar hablante, interlocutor y objeto lírico", "Es el paso intermedio de comprensión."),
   E("El tema de un poema es... A) la idea general B) una palabra repetida", "A) la idea general", "Es de lo que trata.")],
  (f"Lee el poema de ejemplo «{P2}» tres veces. Escribe: 1) quién habla, 2) el tema, 3) el objeto lírico y 4) una palabra o verso que te haya llamado la atención y por qué.",
   "1) Habla un «yo» que se dirige a un «tú» ausente. 2) El tema es seguir adelante después de una ausencia. 3) El objeto lírico es la persona de la foto. 4) Me llamó la atención «guardar no es detener», porque dice que recordar no impide avanzar.",
   ["identifica hablante", "distingue tema y objeto lírico", "justifica un verso destacado"], ["cuatro respuestas"], ["suponer que el hablante es el poeta", "confundir tema con objeto"],
   "Subraya en el poema las palabras que apoyan cada respuesta."),
  "Lee en voz alta un poema que tengas a mano (o el de ejemplo) y anota cómo cambia lo que entiendes en la segunda lectura.",
  "Escribe un poema de cuatro versos que tenga un hablante, un interlocutor y un objeto lírico, y señálalos.")

