L(OA4, 2,
  "Aprenderé a identificar la actitud del hablante hacia el tema (nostalgia, serenidad, ironía, admiración, rabia) con evidencias del poema.",
  ["Reconozco hablante, tema y objeto lírico.", "Distingo emociones como tristeza, alegría o esperanza."],
  ["La actitud del hablante es la manera en que se sitúa frente al tema: con nostalgia, ternura, serenidad, rabia, ironía, admiración, esperanza, entre otras. No es lo mismo el tema (la ausencia) que la actitud (lamentarla o aceptarla). Dos poemas pueden tratar el mismo tema y tener actitudes opuestas.",
   "La actitud se descubre con evidencias del poema: los verbos que usa (guardo, riego, pinté), los adjetivos y sustantivos con carga emocional, las repeticiones («todavía, todavía»), los signos de exclamación e interrogación, el tono y lo que calla. En el poema de la casa vacía, repetir «todavía» muestra que el hablante se aferra al pasado; en el poema de la casa nueva, «Aprendí que guardar no es detener» muestra aceptación.",
   "Para sostener una afirmación sobre la actitud se usa el esquema: actitud, evidencia, explicación. «La actitud es nostálgica: el hablante repite “todavía” y sigue regando el limonero; eso muestra que mantiene vivo el recuerdo». Se evita decir solo «es triste» sin cita. Y se recuerda que una actitud puede ser compleja: puede haber esperanza dentro de la nostalgia."],
  [("actitud del hablante", "manera en que la voz del poema se sitúa ante el tema"), ("nostalgia", "tristeza suave por lo que ya pasó"), ("serenidad", "calma al enfrentar algo"), ("tono", "modo en que suena la voz del poema: tierno, irónico, solemne")],
  [("Actitud con evidencia", f"Poema de ejemplo: «{P1}» ¿Qué actitud tiene el hablante y cuál es una evidencia?",
    ["Repite «todavía» y sigue regando el limonero.", "Se aferra a lo que fue, con tristeza suave.", "La actitud es nostálgica; evidencia: «todavía guardo tu silla»."],
    "Nostálgica; evidencia: «todavía guardo tu silla» y la repetición de «todavía»"),
   ("Mismo tema, distinta actitud", f"Poemas de ejemplo: P1 «{P1}» y P2 «{P2}». Ambos tratan de una ausencia. ¿Cómo difiere la actitud?",
    ["En P1 repite «todavía» y espera: «ya vendrás».", "En P2 pinta, cuelga la foto «no en el centro» y aprende que «guardar no es detener».", "P1 es nostálgico y de espera; P2 es sereno y de aceptación."],
    "P1: nostalgia y espera; P2: serenidad y aceptación")],
  [("Decir que la actitud es «triste» sin citar nada.", "Se opina sin evidencia.", "Cita un verso, una repetición o un verbo que respalde la actitud."),
   ("Confundir el tema con la actitud.", "Se responde con la idea general.", "Pregunta cómo se siente o qué postura toma el hablante frente al tema.")],
  ([E("¿Qué es la actitud del hablante? A) la manera en que se sitúa frente al tema B) el título del poema", "A) la manera en que se sitúa frente al tema", "Muestra su postura emocional."),
    E("¿Cuál de estas es una actitud? A) serenidad B) ausencia", "A) serenidad", "La ausencia es un tema; la serenidad es una forma de enfrentar algo."),
    E("¿Qué recurso puede indicar la actitud del hablante? A) las repeticiones B) la cantidad de páginas del libro", "A) las repeticiones", "Repetir palabras revela insistencia.")],
   [E(f"Poema de ejemplo: «{P2}» ¿Qué verso muestra aceptación? A) «Aprendí que guardar no es detener» B) «Pinté de azul las paredes»", "A) «Aprendí que guardar no es detener»", "Expresa un aprendizaje que permite avanzar."),
    E(f"Poema de ejemplo: «{P1}» ¿Qué actitud sugiere «ya vendrás, ya vendrás»? A) esperanza B) rabia", "A) esperanza", "Confía en que la persona regresará."),
    E("Verso de ejemplo: «¡Qué grande es el cielo cuando tú lo miras!». ¿Qué actitud transmite? A) admiración B) indiferencia", "A) admiración", "La exclamación y el adjetivo «grande» expresan asombro.")],
   [E("Versos de ejemplo: «Me ofreciste un abrazo de cartón, / tan amable que no se podía tocar». ¿Qué actitud tiene el hablante? A) irónica o crítica B) agradecida", "A) irónica o crítica", "Compara el abrazo con cartón: algo falso."),
    E(f"Poema de ejemplo: «{P5}» ¿Qué muestra la repetición de «contigo»? A) cercanía y gratitud hacia el «tú» B) enojo con las calles", "A) cercanía y gratitud hacia el «tú»", "Destaca lo compartido."),
    E(f"Poema de ejemplo: «{P2}» Una lectora dice: «El hablante se queda atrapado en el pasado». ¿Se apoya en el texto? A) no, el poema dice que guardar no es detener B) sí, porque cuelga una foto", "A) no, el poema dice que guardar no es detener", "Colgar la foto «no en el centro» muestra que sigue adelante.")],
   [E(f"Poema de ejemplo: «{P1}» Dos lectores: X: «Hay nostalgia y también esperanza». Y: «Solo hay rabia». ¿Cuál se apoya en el texto? A) X B) Y", "A) X", "«Todavía» sugiere nostalgia y «ya vendrás», esperanza; no hay palabras de enojo."),
    E("Versos de ejemplo: «Hoy no hay sol; / sin embargo, abro la ventana / y cuento los pájaros». ¿Qué actitud se infiere? A) serenidad y atención al detalle B) enojo", "A) serenidad y atención al detalle", "Aun sin sol, se concentra con calma en lo pequeño.")],
   [E(f"Poema de ejemplo: «{P2}» Redacta con el esquema actitud-evidencia-explicación. Elige la mejor opción. A) «La actitud es serena: “La tarde entra y la dejo pasar”; el hablante acepta lo que ocurre sin resistir.» B) «Es lindo.»", "A) «La actitud es serena: “La tarde entra y la dejo pasar”; el hablante acepta lo que ocurre sin resistir.»", "Incluye actitud, cita y explicación."),
    E(f"Poema de ejemplo: «{P1}» ¿Qué verso es la respuesta del hablante al reloj? A) «Y yo le respondo: ya vendrás, ya vendrás.» B) «Todavía, todavía, repite el reloj.»", "A) «Y yo le respondo: ya vendrás, ya vendrás.»", "Es la única respuesta del hablante; el otro verso es lo que dice el reloj.")]),
  [E("Versos de ejemplo: «No me mires con lástima, / que mi voz sigue entera». ¿Qué actitud transmite? A) orgullo y firmeza B) timidez", "A) orgullo y firmeza", "Rechaza la lástima y afirma la entereza de su voz.")],
  [E("¿Qué es el tono de un poema? A) el modo en que suena la voz B) el número de versos", "A) el modo en que suena la voz", "Puede ser tierno, irónico, solemne."),
   E("¿Qué se necesita para sostener una afirmación sobre la actitud? A) una evidencia del poema B) más adjetivos", "A) una evidencia del poema", "Sin evidencia es solo opinión."),
   E("Una actitud puede ser... A) compleja, con varios matices B) siempre única", "A) compleja, con varios matices", "Puede haber nostalgia y esperanza al mismo tiempo.")],
  (f"Lee el poema de ejemplo: «{P5}» Escribe tres oraciones: la actitud del hablante, una evidencia entre comillas y una explicación de cómo la evidencia muestra esa actitud.",
   "La actitud del hablante es de gratitud y cercanía. Evidencia: «contigo el invierno fue un abrigo». Esa imagen muestra que la compañía del «tú» le dio calor y protección en lo difícil.",
   ["nombra la actitud", "cita un verso", "explica la relación"], ["tres oraciones"], ["actitud sin cita", "citar sin explicar"],
   "Marca la cita y comprueba que la explicación no repita la cita."),
  "Escucha una canción actual (sin copiar la letra) y anota la actitud de quien canta y una palabra que la muestra.",
  "Escribe dos versos con actitud irónica y dos con actitud de admiración sobre el mismo tema.")

# ------------------------------------------------------------------ OA 04 · clase 3
FIG = {
    "met": "Tus palabras son puentes de vidrio.",
    "comp": "Mi paciencia, como el río, no se detiene.",
    "pers": "El viento tocó a mi puerta y se fue sin nombre.",
    "hip": "Te esperé mil siglos en el andén.",
}
L(OA4, 3,
  "Aprenderé a reconocer el lenguaje figurado (comparación, metáfora, personificación e hipérbole) y a explicar el efecto que produce en un poema.",
  ["Reconozco hablante, tema y actitud.", "Distingo sentido literal y sentido figurado."],
  ["El lenguaje figurado usa las palabras con un sentido distinto del literal para expresar mejor una emoción o una idea. Cuatro recursos frecuentes son: la comparación, que une dos cosas con un nexo como «como» o «igual que» («mi paciencia, como el río, no se detiene»); la metáfora, que identifica una cosa con otra sin nexo («tus palabras son puentes de vidrio»); la personificación, que da rasgos humanos a algo que no lo es («el viento tocó a mi puerta»); y la hipérbole, que exagera («te esperé mil siglos»).",
   "Reconocer el recurso es solo el primer paso. Lo importante es explicar el efecto o el significado. «Puentes de vidrio» sugiere palabras que comunican, pero que son frágiles y pueden romperse. «Mil siglos» no mide tiempo real: transmite que la espera se sintió interminable. El esquema es: recurso, qué se compara o exagera y qué efecto produce.",
   "Un error común es leer el lenguaje figurado de manera literal o, al revés, nombrar el recurso sin interpretarlo. También hay que evitar decir que «todo es metáfora»: cada recurso tiene rasgos distintos. Si hay «como», es comparación; si no hay nexo y una cosa se identifica con otra, es metáfora. La interpretación se apoya en el contexto del poema: lo que dicen los versos vecinos y la actitud del hablante."],
  [("comparación", "unión de dos cosas mediante un nexo como «como» o «igual que»"), ("metáfora", "identificación de una cosa con otra sin nexo"), ("personificación", "atribución de rasgos humanos a algo que no es humano"), ("hipérbole", "exageración para dar énfasis")],
  [("Reconocer y explicar", f"Verso de ejemplo: «{FIG['met']}» ¿Qué recurso es y qué sugiere?",
    ["No hay «como»; las palabras se identifican con puentes de vidrio: es metáfora.", "Los puentes comunican, pero el vidrio es frágil.", "Sugiere palabras que unen pero se rompen con facilidad."],
    "Metáfora: palabras que comunican, pero son frágiles"),
   ("Distinguir dos recursos parecidos", f"Versos de ejemplo: A) «{FIG['comp']}» B) «{FIG['pers']}». ¿Cuál es comparación y cuál personificación?",
    ["En A aparece «como»: une la paciencia con el río.", "En B el viento hace algo humano: tocar a la puerta.", "A es comparación; B es personificación."],
    "A es comparación; B es personificación")],
  [("Nombrar el recurso sin explicar su efecto.", "Se reconoce la figura, pero no se interpreta.", "Agrega qué se compara o exagera y qué sentido o emoción aporta."),
   ("Confundir comparación con metáfora.", "Se olvida revisar si hay un nexo.", "Si hay «como» o «igual que», es comparación; si no, puede ser metáfora.")],
  ([E(f"Verso de ejemplo: «{FIG['hip']}» ¿Qué recurso es? A) hipérbole B) comparación", "A) hipérbole", "Exagera el tiempo de espera."),
    E(f"Verso de ejemplo: «{FIG['pers']}» ¿Qué recurso es? A) personificación B) hipérbole", "A) personificación", "El viento realiza una acción humana: tocar."),
    E(f"Verso de ejemplo: «{FIG['comp']}» ¿Qué palabra funciona como nexo? Escribe la palabra.", "como", "Une la paciencia con el río.")],
   [E(f"Verso de ejemplo: «{FIG['hip']}» ¿Qué efecto produce «mil siglos»? A) transmite una espera interminable B) mide con exactitud el tiempo", "A) transmite una espera interminable", "La exageración enfatiza lo largo que se sintió."),
    E("Verso de ejemplo: «La luna es una moneda olvidada en el cielo». ¿Qué recurso es? A) metáfora B) comparación", "A) metáfora", "Identifica la luna con una moneda sin nexo."),
    E("Verso de ejemplo: «La luna, como una moneda, brillaba en el cielo». ¿Qué recurso es? A) comparación B) metáfora", "A) comparación", "Usa el nexo «como».")],
   [E("Verso de ejemplo: «La ciudad se despertó bostezando». ¿Qué recurso aparece y por qué? A) personificación, porque la ciudad bosteza como una persona B) hipérbole, porque exagera", "A) personificación, porque la ciudad bosteza como una persona", "Atribuye una acción humana a un lugar."),
    E("Verso de ejemplo: «Mi mochila pesaba toneladas». ¿Qué efecto produce? A) enfatiza lo pesada que se sentía B) informa su peso real", "A) enfatiza lo pesada que se sentía", "Es una hipérbole que comunica una sensación."),
    E("Verso de ejemplo: «Sus manos, como pájaros, volaban sobre el piano». ¿Qué sugiere la comparación? A) que las manos se movían con ligereza y rapidez B) que había pájaros en la sala", "A) que las manos se movían con ligereza y rapidez", "Se resalta el movimiento ligero de las manos.")],
   [E(f"Verso de ejemplo: «{FIG['met']}» Una lectora dice: «Significa que las palabras son de vidrio de verdad». ¿Qué error comete? A) lee de manera literal una metáfora B) interpreta con el contexto", "A) lee de manera literal una metáfora", "Los puentes de vidrio son una imagen, no objetos reales."),
    E("Un lector dice: «Todo lo que tiene un adjetivo bonito es metáfora». ¿Es correcto? A) no, la metáfora identifica una cosa con otra B) sí", "A) no, la metáfora identifica una cosa con otra", "Un adjetivo no basta para que haya metáfora."),
    E("Versos de ejemplo: «El otoño dejó sus cartas amarillas en el suelo». ¿Qué crees que representan «cartas amarillas»? A) las hojas caídas B) las cartas del correo", "A) las hojas caídas", "Es una metáfora para las hojas secas del otoño.")],
   [E("Verso de ejemplo: «La noche, tosiendo frío, se sentó a esperarme mil años en la puerta». ¿Qué dos recursos aparecen? A) personificación e hipérbole B) comparación y metáfora", "A) personificación e hipérbole", "La noche tose y se sienta como una persona; «mil años» exagera la espera. No hay «como» ni una identificación entre dos cosas."),
    E("Dos frases dicen que alguien tiene sueño. ¿Cuál usa lenguaje figurado? A) «Tengo un millón de sueños en los párpados» B) «Hoy dormí poco»", "A) «Tengo un millón de sueños en los párpados»", "Usa una exageración e imagen; la otra mantiene el sentido literal.")],
   [E("Poema de ejemplo: «La tarde, una herida abierta, / se vierte sobre el tejado; / el viento, con voz de lija, / me pregunta por tus pasos». Identifica el recurso de «La tarde, una herida abierta» y el de «el viento […] me pregunta». A) metáfora y personificación B) comparación e hipérbole", "A) metáfora y personificación", "La tarde se identifica con una herida y el viento realiza una acción humana."),
    E("En el mismo poema, «con voz de lija» es un recurso. ¿Qué sentido aporta? A) una voz áspera B) una voz dulce", "A) una voz áspera", "La lija es rugosa; transmite aspereza al sonido del viento.")]),
  [E("Poema de ejemplo: «Mi abuela cose los días / con hilo de paciencia. / El invierno, ese viejo, / le pregunta por su aguja». ¿Cuál afirmación es correcta? A) «con hilo de paciencia» es metáfora y «ese viejo» personifica al invierno B) «con hilo de paciencia» es hipérbole", "A) «con hilo de paciencia» es metáfora y «ese viejo» personifica al invierno", "La paciencia se identifica con hilo, y el invierno recibe rasgos humanos.")],
  [E("¿Qué recurso exagera? A) la hipérbole B) la personificación", "A) la hipérbole", "Exagerar es su rasgo."),
   E("¿Qué recurso usa «como» para unir dos cosas? A) la comparación B) la metáfora", "A) la comparación", "El nexo «como» la identifica."),
   E("Explicar el efecto de un recurso significa... A) decir qué sentido o emoción aporta B) repetir el verso", "A) decir qué sentido o emoción aporta", "No basta nombrar la figura.")],
  ("Escribe cuatro versos de ejemplo sobre la lluvia, con una comparación, una metáfora, una personificación y una hipérbole. Marca cada uno con la palabra del recurso entre paréntesis y explica en una oración el efecto de uno de ellos.",
   "La lluvia cae como un coro de dedos pequeños (comparación). La calle es un espejo lleno de cielos (metáfora). El techo se queja bajo el agua (personificación). Llovió mil días sobre mi paraguas (hipérbole). Efecto del cuarto: exagera lo largo y cansador que fue el aguacero.",
   ["cuatro recursos distintos", "marca cada uno", "explica un efecto"], ["cuatro versos y una explicación"], ["versos sin recurso", "no explicar el efecto"],
   "Comprueba que cada verso tenga solo el recurso que marcaste."),
  "Busca en tu casa una frase publicitaria o un dicho que use lenguaje figurado y anota qué recurso es.",
  "Escribe un verso con personificación del reloj y otro con hipérbole de una espera.")

# ------------------------------------------------------------------ OA 04 · clase 4
STR = "En la casa del abuelo suena el sauce, susurra el viento y sube el sol sin prisa."
L(OA4, 4,
  "Aprenderé a reconocer repeticiones de estructuras, sonidos, palabras e ideas en un poema (anáfora, paralelismo, estribillo, aliteración, rima) y a contrastar interpretaciones de su efecto.",
  ["Reconozco lenguaje figurado y actitud del hablante.", "Sé qué es una rima."],
  ["La repetición es uno de los recursos más importantes de la poesía. Puede repetirse una palabra al comienzo de varios versos (anáfora: «contigo… contigo… contigo»), una estructura gramatical (paralelismo), un verso o grupo de versos (estribillo), un sonido consonántico (aliteración: «el susurro del sauce sobre el sendero») o los sonidos finales de los versos (rima). Cada repetición crea un ritmo y destaca algo.",
   "El efecto se interpreta en relación con el sentido. En el poema que repite «contigo», la anáfora subraya cuánto significó la compañía. En «Todavía, todavía», la repetición muestra insistencia y apego. La aliteración de la s en «susurro del sauce» imita el sonido del viento: el sonido refuerza lo que se dice. Y la rima une los versos y da musicalidad, además de relacionar significados.",
   "Dos lectores pueden interpretar el efecto de una misma repetición de modo distinto. Uno puede decir que la repetición de «ya vendrás» expresa esperanza; otro, que expresa una duda que se intenta convencer. Ambas lecturas son válidas si se apoyan en el texto, por ejemplo, en el hecho de que el hablante lo repite dos veces como si necesitara convencerse. Conviene contrastarlas y decidir cuál tiene más respaldo."],
  [("anáfora", "repetición de una palabra o frase al comienzo de varios versos"), ("aliteración", "repetición de un sonido consonántico a lo largo del verso"), ("estribillo", "verso o grupo de versos que se repite"), ("rima", "coincidencia de sonidos al final de los versos")],
  [("Reconocer la repetición", f"Poema de ejemplo: «{P5}» ¿Qué repetición hay y qué efecto produce?",
    ["La palabra «contigo» abre los cuatro versos.", "Eso es una anáfora.", "Destaca la presencia del «tú» en cada recuerdo."],
    "Anáfora de «contigo»: destaca la presencia del «tú» en cada recuerdo"),
   ("Aliteración y sentido", f"Verso de ejemplo: «{STR}» ¿Qué sonido se repite y qué sugiere?",
    ["Se repite el sonido s: «suena», «sauce», «susurra», «sube», «sol», «sin».", "Es una aliteración.", "Imita el susurro del viento entre las hojas."],
    "Aliteración de la s: imita el susurro del viento")],
  [("Decir que la repetición es un defecto o un relleno.", "Se piensa que repetir es no tener ideas.", "Pregunta qué se destaca al repetir y qué ritmo crea."),
   ("Nombrar el recurso sin decir su efecto.", "Se detecta, pero no se interpreta.", "Agrega qué se enfatiza o qué sensación produce.")],
  ([E("¿Qué es una anáfora? A) repetir una palabra al comienzo de varios versos B) repetir los sonidos finales", "A) repetir una palabra al comienzo de varios versos", "Es una repetición inicial."),
    E("¿Qué es una rima? A) coincidencia de sonidos al final de los versos B) comparación entre dos cosas", "A) coincidencia de sonidos al final de los versos", "Une los versos por su sonido."),
    E(f"Poema de ejemplo: «{P3}» ¿Qué palabras riman con «puerto»? Escribe la palabra.", "cierto", "Comparten los sonidos finales «-erto».")],
   [E(f"Poema de ejemplo: «{P3}» ¿Con qué palabra rima «hablar»? Escribe la palabra.", "zarpar", "Comparten los sonidos finales «-ar»."),
    E(f"Poema de ejemplo: «{P1}» ¿Qué palabra se repite al comienzo de varios versos? A) todavía B) tarde", "A) todavía", "Abre el primer y el segundo verso, y vuelve en el quinto."),
    E("Versos de ejemplo: «Corre el río, corre el tiempo, corre el día». ¿Qué recurso se repite? A) una anáfora y un paralelismo con «corre» B) una rima", "A) una anáfora y un paralelismo con «corre»", "Repite la palabra y la estructura al comienzo de cada parte.")],
   [E("Versos de ejemplo: «Pasa el tren, pasa la noche, pasa el miedo». ¿Qué efecto produce el paralelismo? A) da ritmo y sugiere que todo pasa B) indica que el tren es lento", "A) da ritmo y sugiere que todo pasa", "La estructura repetida refuerza la idea de lo pasajero."),
    E("Verso de ejemplo: «El rumor de los remos rompe el río». ¿Qué sonido consonántico se repite más? A) la r B) la m", "A) la r", "Aparece en «rumor», «remos», «rompe», «río»."),
    E("Estribillo de ejemplo: «Ya vendrás, ya vendrás». Aparece al final de cada estrofa de un poema de tres estrofas. ¿Cuántas veces se escucha el estribillo completo?", "3", "Una vez en cada estrofa: tres en total.")],
   [E(f"Poema de ejemplo: «{P1}» Lectura X: «Repetir “ya vendrás” expresa esperanza». Lectura Y: «Repetirlo muestra que el hablante necesita convencerse». ¿Ambas pueden ser válidas? A) sí, si cada una se apoya en el texto B) no, solo una", "A) sí, si cada una se apoya en el texto", "El poema admite más de una lectura con evidencia."),
    E(f"Poema de ejemplo: «{P5}» Un lector dice: «Repetir “contigo” muestra que el hablante está enojado». ¿Qué le falta? A) evidencia; el poema sugiere más bien cercanía y gratitud B) otra repetición", "A) evidencia; el poema sugiere más bien cercanía y gratitud", "Versos como «el invierno fue un abrigo» no expresan enojo."),
    E("Versos de ejemplo: «Cae la nieve, cae el silencio, cae la noche». ¿Qué relación hay entre la repetición de «cae» y el sentido? A) la repetición imita un descenso lento y continuo B) la repetición indica velocidad", "A) la repetición imita un descenso lento y continuo", "El verbo «caer» insiste en el movimiento descendente.")],
   [E("Poema de ejemplo: «Quiero el mar, quiero la sal, / quiero el barco y el timón; / quiero irme sin mirar / a la tierra donde estoy». ¿Qué anáfora hay y qué muestra? A) «quiero», que muestra deseo intenso de partir B) «mar», que muestra que le gusta pescar", "A) «quiero», que muestra deseo intenso de partir", "La repetición de «quiero» insiste en un deseo."),
    E("Dos lectores analizan el verso: «Llueve, llueve, llueve sobre mi cansancio». X dice que la repetición imita la lluvia. Y dice que muestra la insistencia del cansancio. ¿Qué haces? A) evalúas cuál se apoya mejor en el poema o aceptas ambas B) descartas ambas", "A) evalúas cuál se apoya mejor en el poema o aceptas ambas", "Las dos son posibles; se pueden complementar.")],
   [E("Verso de ejemplo: «El sol se sumerge en el sur, silencioso». ¿Qué sonido consonántico se repite? A) la s B) la m", "A) la s", "Aparece en «sol», «se», «sumerge», «sur» y «silencioso»; la m aparece solo una vez, en «sumerge»."),
    E("Poema de ejemplo: «Soy río, / soy puente, / soy ladrillo. / Soy casa». ¿Qué recurso se repite al comienzo de los versos? A) anáfora B) aliteración", "A) anáfora", "Repite «Soy» al comienzo de los versos.")]),
  [E("Poema de ejemplo: «Por la ventana entra el sol, / por la puerta entra el frío; / por el patio entra el olvido, / por tus ojos entro yo». ¿Qué recurso estructura el poema? A) anáfora y paralelismo con «por…entra» B) rima en cada verso", "A) anáfora y paralelismo con «por…entra»", "Se repite la estructura «por + lugar + entra».")],
  [E("El estribillo es... A) un verso o grupo que se repite B) la rima de todos los versos", "A) un verso o grupo que se repite", "Aparece varias veces."),
   E("La aliteración repite... A) un sonido consonántico B) una estructura", "A) un sonido consonántico", "Genera efectos sonoros."),
   E("Interpretar el efecto de una repetición significa... A) explicar qué destaca o qué ritmo crea B) contar cuántas veces aparece", "A) explicar qué destaca o qué ritmo crea", "Hay que vincularla con el sentido.")],
  (f"Lee el poema de ejemplo «{P3}» y escribe cuatro oraciones: 1) qué rima hay, 2) qué palabras riman, 3) qué otro recurso de repetición podrías reconocer (por ejemplo, un sonido repetido) y 4) un efecto de la rima en el poema.",
   "1) Hay rima en los versos primero y tercero, y en el segundo y cuarto. 2) Riman «puerto» con «cierto» y «hablar» con «zarpar». 3) Se repite el sonido de la r en varias palabras. 4) La rima da musicalidad y une los versos, y relaciona la idea del viaje con el deseo de partir.",
   ["identifica la rima", "nombra las palabras", "explica un efecto"], ["cuatro oraciones"], ["inventar rimas", "no explicar el efecto"],
   "Subraya las palabras que riman y marca su sonido final."),
  "Escucha una canción actual y anota un estribillo, sin copiar más de una frase.",
  "Escribe cuatro versos de ejemplo con anáfora de «quiero» y explica su efecto.")

# ------------------------------------------------------------------ OA 04 · clase 5
SIMB = "Poema de ejemplo: «El río de mi calle / no tiene puente ni nombre; / lo cruzo cada mañana / y el agua me cambia el rostro»."
L(OA4, 5,
  "Aprenderé a reconocer símbolos en un poema, a interpretarlos con apoyo del contexto y a situar sus posibles sentidos culturales.",
  ["Reconozco lenguaje figurado y repeticiones.", "Sé que algunas imágenes representan ideas."],
  ["Un símbolo es un elemento concreto (un río, una puerta, un camino, una paloma, una luz) que representa una idea más amplia. A diferencia de una metáfora aislada, un símbolo suele repetirse o recibir un lugar central, y su sentido se construye con el resto del poema. El río puede simbolizar el paso del tiempo y los cambios de la vida; el camino, el rumbo de una persona; la puerta, una oportunidad o una despedida.",
   "Muchos símbolos tienen sentidos que comparte una cultura: la paloma blanca suele asociarse a la paz; el fuego, a la pasión o la destrucción; el mar, a lo inmenso o al viaje. Pero cada poema puede cambiarlos. Por eso hay que mirar el contexto interno (qué dice el poema alrededor del símbolo) y, cuando corresponde, el contexto externo (la época o cultura en que se escribió). La interpretación se apoya en ambos, sin inventar datos históricos.",
   "Para interpretar un símbolo: primero se nombra el elemento; luego se observan sus rasgos en el poema (cómo se describe, qué hace el hablante con él); después se propone qué idea puede representar y se respalda con una cita. Una buena lectura reconoce que el símbolo admite más de un sentido, pero todos deben ser compatibles con el texto."],
  [("símbolo", "elemento concreto que representa una idea más amplia"), ("contexto interno", "lo que dice el poema alrededor de un elemento"), ("contexto externo", "época, cultura o situación en que se escribió el poema"), ("connotación", "sentido añadido que una palabra evoca más allá de su significado literal")],
  [("Interpretar con el contexto interno", f"{SIMB} ¿Qué puede simbolizar el río?",
    ["El hablante lo cruza cada mañana y dice que el agua le cambia el rostro.", "Un río que cambia a quien lo cruza sugiere cambio y paso del tiempo.", "Puede simbolizar el tiempo o los cambios de la vida cotidiana."],
    "El paso del tiempo o los cambios que transforman a la persona"),
   ("Sentido cultural y sentido propio", "Poema de ejemplo: «La paloma que se posó en mi ventana / traía en el pico una hoja rota». ¿Cómo se relaciona con el símbolo cultural de la paloma?",
    ["La paloma suele asociarse a la paz.", "Aquí trae una hoja rota: la paz aparece dañada o incompleta.", "El poema usa el símbolo cultural, pero lo matiza."],
    "Usa el símbolo de la paz, pero lo matiza: es una paz dañada o incompleta")],
  [("Dar un significado fijo a un símbolo sin mirar el poema.", "Se aplica un diccionario de símbolos.", "Observa cómo se describe en ese poema y qué hace el hablante."),
   ("Inventar un dato histórico para sostener una interpretación.", "Se agrega información que no se conoce.", "Usa solo el texto y lo que sepas con certeza.")],
  ([E("¿Qué es un símbolo en poesía? A) un elemento concreto que representa una idea más amplia B) la firma del poeta", "A) un elemento concreto que representa una idea más amplia", "Va más allá de su sentido literal."),
    E("La paloma blanca suele asociarse con... A) la paz B) el miedo", "A) la paz", "Es un símbolo cultural frecuente."),
    E(f"{SIMB} ¿Qué elemento concreto es el eje del poema? A) el río B) la calle", "A) el río", "El poema parte del río de la calle y todo lo demás ocurre al cruzarlo.")],
   [E(f"{SIMB} ¿Qué verso sugiere el cambio? A) «el agua me cambia el rostro» B) «no tiene puente ni nombre»", "A) «el agua me cambia el rostro»", "Dice que cruzar el río transforma al hablante."),
    E("Poema de ejemplo: «Llegué a la puerta cerrada / y no toqué: / escuché el mundo detrás de la madera». ¿Qué puede simbolizar la puerta? A) una oportunidad o una barrera ante algo nuevo B) un mueble", "A) una oportunidad o una barrera ante algo nuevo", "El hablante duda y escucha lo que hay detrás."),
    E("Poema de ejemplo: «El camino se bifurca: / elegí el de piedras, / porque el otro olía a ayer». ¿Qué puede simbolizar el camino? A) las decisiones de la vida B) un paseo", "A) las decisiones de la vida", "La bifurcación plantea elegir entre dos rumbos.")],
   [E("Poema de ejemplo: «Encendí una vela contra la tormenta; / la sombra se hizo pequeña / y yo, grande». ¿Qué puede simbolizar la vela? A) la esperanza o el valor frente a la dificultad B) el cumpleaños", "A) la esperanza o el valor frente a la dificultad", "La vela hace retroceder la sombra."),
    E("Poema de ejemplo: «La paloma que se posó en mi ventana / traía en el pico una hoja rota». Una lectora dice: «Expresa una paz imperfecta». ¿Qué evidencia respalda su lectura? A) «una hoja rota» B) «mi ventana»", "A) «una hoja rota»", "La rotura sugiere imperfección."),
    E("Poema de ejemplo: «El mar no me contestó, pero me devolvió mi voz». ¿Qué puede simbolizar el mar? A) lo inmenso, que refleja la propia voz B) un lugar de vacaciones", "A) lo inmenso, que refleja la propia voz", "El mar devuelve la voz del hablante: es espejo de su interior.")],
   [E(f"{SIMB} Dos lectores interpretan el río del poema. X: «Simboliza el tiempo». Y: «Simboliza los cambios de la persona». ¿Qué relación hay? A) son compatibles y se complementan B) se excluyen", "A) son compatibles y se complementan", "El tiempo produce cambios en las personas."),
    E("Poema de ejemplo: «El fuego devoró el puente / y no quedó ni la orilla». Un lector dice: «El fuego simboliza la paz». ¿Qué debe revisar? A) si el contexto interno respalda ese sentido B) cuántos versos tiene el poema", "A) si el contexto interno respalda ese sentido", "Aquí el fuego destruye el puente y la orilla; un símbolo se interpreta con el poema, no con una etiqueta fija.")],
   [E("Poema de ejemplo: «El árbol de mi patio / guarda mi altura de niña / en una marca de la corteza». ¿Qué puede simbolizar el árbol? A) el paso del tiempo y la memoria B) un elemento decorativo", "A) el paso del tiempo y la memoria", "Conserva una marca de la infancia."),
    E("Un lector sostiene: «El árbol simboliza la memoria». ¿Qué cita lo respalda? A) «guarda mi altura de niña» B) «de mi patio»", "A) «guarda mi altura de niña»", "Habla de conservar algo del pasado.")]),
  [E("Poema de ejemplo: «Soltó la cometa en el viento, / hilo en la mano, la vista en alto; / cuando el hilo se rompió, / sonrió y la dejó irse». ¿Qué puede simbolizar la cometa? A) un deseo o un sueño que se deja libre B) un juguete", "A) un deseo o un sueño que se deja libre", "La actitud de sonreír ante la ruptura sugiere aceptación.")],
  [E("Para interpretar un símbolo hay que mirar... A) el contexto interno del poema B) solo un diccionario", "A) el contexto interno del poema", "El sentido se construye con el texto."),
   E("Un símbolo puede tener... A) más de un sentido compatible con el texto B) un solo sentido para todos los poemas", "A) más de un sentido compatible con el texto", "La lectura admite matices."),
   E("Un símbolo cultural es... A) un elemento al que una cultura asocia un significado B) un elemento inventado en cada poema", "A) un elemento al que una cultura asocia un significado", "Por ejemplo, la paloma y la paz.")],
  ("Lee el poema de ejemplo: «Subimos por la escalera sin luz, / tanteando la pared con la memoria. / En el último peldaño había una ventana / y, afuera, el mundo entero esperando». Escribe tres oraciones: qué elemento puede ser un símbolo, qué puede representar y qué verso lo respalda.",
   "La escalera puede ser un símbolo. Representa el esfuerzo de avanzar hacia algo nuevo aun sin ver claro. Lo respalda el verso «tanteando la pared con la memoria», que muestra que avanzan con dificultad pero con guía interior, y el final, donde la ventana abre al «mundo entero».",
   ["propone un símbolo", "explica qué representa", "cita un verso"], ["tres oraciones"], ["significado fijo sin contexto", "cita que no respalda"],
   "Subraya el verso citado y comprueba que justifique el sentido propuesto."),
  "Observa un objeto en tu casa que pueda representar una idea (una puerta, una ventana) y anota qué idea.",
  "Escribe cuatro versos de ejemplo donde una ventana sea un símbolo y explica de qué.")

# ------------------------------------------------------------------ OA 04 · clase 6
L(OA4, 6,
  "Aprenderé a relacionar los aspectos formales de un poema (versos, estrofas, rima, puntuación, extensión) con su significado y a formular una lectura propia.",
  ["Reconozco hablante, actitud, lenguaje figurado, repeticiones y símbolos.", "Sé qué es verso, estrofa y rima."],
  ["Los aspectos formales son los rasgos externos del poema: cuántos versos tiene, cómo se agrupan en estrofas, si hay rima o no, cuán largos son los versos, cómo se usa la puntuación. Un poema en verso libre no sigue una rima ni una medida fija; uno rimado organiza sus versos con regularidad. Un verso muy corto marca una pausa; uno largo, un aliento extenso.",
   "La forma no es un adorno: contribuye al significado. En el poema de las barcas, la cuarteta con rima regular da un ritmo de vaivén, como las olas en el puerto. En el poema de la casa vacía, el verso libre y las pausas hacen que el habla parezca natural, como un pensamiento en voz baja. Si un poema termina con un verso muy corto, la brevedad puede sugerir silencio o cierre. La pregunta clave es: ¿qué sentido refuerza este rasgo formal?",
   "Para formular una lectura propia se combinan los aspectos del OA: se plantea una idea sobre el sentido, se apoya en un rasgo de forma (rima, estrofa, puntuación) y en uno de contenido (símbolo, lenguaje figurado, actitud), y se cita. Por ejemplo: «El verso final, breve y sin rima, deja un silencio que refuerza la sensación de espera». Una lectura sólida no inventa efectos que la forma no produce."],
  [("aspectos formales", "rasgos externos del poema: versos, estrofas, rima, puntuación"), ("verso libre", "verso sin rima ni medida fija"), ("estrofa", "grupo de versos separados de otro por un espacio"), ("cuarteta", "estrofa de cuatro versos")],
  [("Forma y sentido", f"Poema de ejemplo: «{P3}» ¿Qué relación hay entre su forma regular y su tema?",
    ["Es una cuarteta de cuatro versos con rima regular.", "El tema es el movimiento de las barcas que quieren partir.", "El ritmo regular sugiere un vaivén, como las olas o el balanceo de las barcas."],
    "La rima regular crea un vaivén que acompaña el movimiento de las barcas"),
   ("Una lectura propia con forma y contenido", f"Poema de ejemplo: «{P1}» Formula una lectura que combine el verso libre y la repetición de «todavía».",
    ["El verso libre da naturalidad, como un pensamiento en voz baja.", "«Todavía» se repite y refuerza la insistencia.", "Lectura: la forma libre y la repetición muestran un recuerdo que no cesa, dicho con sencillez."],
    "La forma libre y la repetición muestran un recuerdo persistente dicho con sencillez")],
  [("Decir que la rima «hace bonito» sin relacionarla con el sentido.", "Se ve la forma como adorno.", "Pregunta qué sentido o emoción refuerza el rasgo formal."),
   ("Inventar efectos que la forma no produce.", "Se fuerza una interpretación.", "Cita el rasgo formal observable y explica solo lo que aporta.")],
  ([E("¿Qué es una cuarteta? A) una estrofa de cuatro versos B) un verso de cuatro sílabas", "A) una estrofa de cuatro versos", "Cuarteta alude a cuatro versos."),
    E("Un poema en verso libre... A) no sigue rima ni medida fija B) siempre tiene rima", "A) no sigue rima ni medida fija", "Esa es su característica."),
    E(f"Poema de ejemplo: «{P2}» ¿Tiene rima regular? A) no, es verso libre B) sí, en todos los versos", "A) no, es verso libre", "Sus versos terminan en sonidos distintos y tienen extensiones desiguales.")],
   [E(f"Poema de ejemplo: «{P3}» ¿Qué tipo de estrofa es? A) una cuarteta B) una estrofa de seis versos", "A) una cuarteta", "Tiene cuatro versos."),
    E(f"Poema de ejemplo: «{P2}» ¿Qué sentido aporta el cierre con «el limonero también florece en otro patio»? A) sugiere que la vida continúa en otro lugar B) sugiere que todo se detiene", "A) sugiere que la vida continúa en otro lugar", "El limonero florece de nuevo, aunque en otro patio."),
    E("Poema de ejemplo: «Espero. / Nada. / Espero». ¿Qué sugieren los versos muy cortos? A) silencio y vacío B) un viaje largo", "A) silencio y vacío", "La brevedad y las pausas refuerzan el sentido.")],
   [E(f"Poema de ejemplo: «{P3}» Una lectora dice: «La rima regular acompaña la idea de un vaivén». ¿Está bien fundamentada? A) sí, porque el ritmo regular se parece al balanceo de las barcas B) no, porque la rima no tiene efectos", "A) sí, porque el ritmo regular se parece al balanceo de las barcas", "Relaciona un rasgo formal observable con el sentido."),
    E("Poema de ejemplo en verso libre: «Cuando me dijeron que te habías ido / no lloré, / puse la mesa para dos, / y esperé». ¿Qué sugiere el último verso breve? A) un silencio de espera B) una celebración", "A) un silencio de espera", "El verso corto concentra la acción de esperar."),
    E("Poema de ejemplo: «¡Corre! ¡Salta! ¡Vuela! ¡No te detengas!». ¿Qué efecto producen los signos de exclamación y los verbos cortos? A) urgencia y energía B) calma", "A) urgencia y energía", "Los imperativos exclamativos aceleran el ritmo.")],
   [E(f"Poema de ejemplo: «{P1}» Lectura: «El verso libre y el final con repetición muestran una espera sin descanso». ¿Qué elemento de forma respalda la lectura? A) la repetición de «ya vendrás» al final B) el número de versos", "A) la repetición de «ya vendrás» al final", "Insistir al final refuerza la espera."),
    E("Un estudiante dice: «Los poemas rimados son mejores que los de verso libre». ¿Qué crítica merece? A) una forma no es mejor por sí misma; vale por lo que aporta al sentido B) los de verso libre no existen", "A) una forma no es mejor por sí misma; vale por lo que aporta al sentido", "La forma se evalúa según su efecto en el poema.")],
   [E(f"Poema de ejemplo: «{P2}» ¿Qué verso menciona un cambio de lugar para el recuerdo? A) «Colgué tu foto en el pasillo, no en el centro» B) «La tarde entra y la dejo pasar»", "A) «Colgué tu foto en el pasillo, no en el centro»", "La foto pasa del centro al pasillo: el recuerdo se reubica."),
    E("Un lector formula: «El último verso, breve y sin rima, deja un silencio que refuerza la sensación de espera». Un compañero dice que esa lectura tiene tres partes: forma, efecto y sentido. ¿Cuál es el rasgo formal? A) el último verso breve y sin rima B) la sensación de espera", "A) el último verso breve y sin rima", "Es el rasgo observable; la espera es el sentido.")]),
  [E("Poema de ejemplo: «Ayer / llovió / sobre / todas / las / cosas». ¿Qué sugiere la distribución de una palabra por línea? A) una lluvia lenta y gota a gota B) una carrera", "A) una lluvia lenta y gota a gota", "La disposición vertical imita la caída de las gotas.")],
  [E("¿Qué es un aspecto formal? A) un rasgo externo, como estrofa o rima B) la emoción del hablante", "A) un rasgo externo, como estrofa o rima", "Se observa en cómo está escrito."),
   E("La forma de un poema... A) contribuye al significado B) es solo adorno", "A) contribuye al significado", "Puede reforzar la emoción o la idea."),
   E("Una lectura propia sólida combina... A) forma y contenido con citas B) solo opiniones", "A) forma y contenido con citas", "Así se sostiene con evidencia.")],
  (f"Lee el poema de ejemplo «{P2}» y escribe una lectura propia de cinco líneas que relacione un aspecto formal (verso libre, extensión de los versos o puntuación) con el sentido, e incluya una cita.",
   "El poema está en verso libre, sin rima, lo que le da un tono cotidiano, como una conversación íntima. Esa sencillez acompaña un contenido de aceptación: «Aprendí que guardar no es detener». El último verso cierra con una imagen amplia: «el limonero también florece en otro patio», como si la vida pudiera seguir creciendo en otro lugar.",
   ["relaciona forma y sentido", "cita un verso", "no inventa efectos"], ["lectura de cinco líneas"], ["forma como adorno", "cita que no se relaciona"],
   "Subraya el rasgo formal y la cita; comprueba que la explicación los una."),
  "Cuenta los versos y las estrofas de un poema que tengas a mano y anota si tiene rima.",
  "Escribe dos versiones de un mismo mensaje: una en verso libre y otra rimada, y compara el efecto.")

# ------------------------------------------------------------------ OA 04 · clase 7
NAR = ("Poema de ejemplo, «Pozo»: Me miro en el agua del pozo / y no me reconozco; / Narciso se habría quedado más tiempo, / yo me voy a tomar el té.")
L(OA4, 7,
  "Aprenderé a reconocer relaciones intertextuales en un poema (alusiones, epígrafes, reescrituras) y a revisar y transferir un análisis a un poema nuevo.",
  ["Analizo hablante, actitud, lenguaje figurado, repeticiones, símbolos y forma.", "Conozco algunos mitos."],
  ["La intertextualidad en poesía aparece cuando un poema remite a otra obra: con una alusión (nombrar a Narciso, a Ícaro, a Ulises o a Prometeo), un epígrafe (una frase breve de otro texto al comienzo, con su autor), una cita o una reescritura. Narciso es el personaje del mito griego que se enamoró de su propio reflejo en el agua. Un poema que lo menciona espera que el lector recuerde ese mito y observe qué hace el poema con él. Otros ejemplos: Ícaro voló con alas de cera y cayó al acercarse al sol; Prometeo entregó el fuego a los humanos; Ulises (u Odiseo) es el héroe de la Odisea, que narra su regreso a casa tras la guerra de Troya, contada en la Ilíada.",
   "Analizar la alusión implica preguntarse: ¿qué sentido tiene la obra aludida?, ¿el poema lo repite, lo invierte o lo ironiza? En «Pozo», el hablante se mira en el agua como Narciso, pero no se queda contemplándose: se va a tomar el té. El poema invierte el mito con humor y muestra una actitud de distancia hacia el culto a uno mismo. Sin conocer a Narciso, el poema se entiende a medias.",
   "La revisión final comprueba el análisis con una pauta: ¿identifiqué al hablante y su actitud?, ¿expliqué al menos dos recursos y su efecto?, ¿relacioné forma y significado?, ¿cité los versos?, ¿expliqué la relación intertextual sin inventar? Transferir es aplicar la pauta a un poema nuevo. El método es el mismo, y cada poema pide ajustes: unos destacan los símbolos, otros la repetición o la alusión."],
  [("intertextualidad", "relación de un texto con otras obras"), ("epígrafe", "frase breve de otra obra que se coloca al comienzo de un texto"), ("alusión", "referencia breve a un personaje, hecho u obra"), ("pauta de revisión", "lista de preguntas para evaluar un análisis")],
  [("Interpretar una alusión", f"{NAR} ¿Qué alusión aparece y cómo la transforma el poema?",
    ["Nombra a Narciso, que se enamoró de su reflejo.", "El hablante, en cambio, no se queda mirándose: se va a tomar el té.", "Invierte el mito con humor."],
    "Alude a Narciso y lo invierte con humor: el hablante no se queda contemplándose"),
   ("Revisar con pauta", "Análisis de ejemplo del poema «Pozo»: «El poema es divertido». ¿Qué le falta según la pauta?",
    ["No identifica la actitud con evidencia.", "No menciona la alusión ni cita versos.", "Debe agregar la actitud con cita y explicar la alusión."],
    "Le falta actitud con evidencia, la alusión explicada y citas")],
  [("Nombrar la alusión sin explicar qué hace el poema con ella.", "Se menciona el nombre, pero no el sentido.", "Explica si el poema repite, invierte o ironiza lo que se espera de la obra aludida."),
   ("Entregar el análisis sin revisar.", "Se cree que está listo al terminar de escribir.", "Relee con una pauta y corrige lo que falte.")],
  ([E("¿Qué es un epígrafe? A) una frase breve de otra obra al comienzo de un texto B) el título del libro", "A) una frase breve de otra obra al comienzo de un texto", "Se coloca al inicio, con su autor."),
    E("Narciso, en el mito griego, es el personaje que... A) se enamoró de su propio reflejo B) venció a un monstruo", "A) se enamoró de su propio reflejo", "Es el mito conocido que alude el poema."),
    E("Una alusión es... A) una referencia breve a algo conocido B) una cita larga", "A) una referencia breve a algo conocido", "No reproduce la obra.")],
   [E(f"{NAR} ¿Qué hace el hablante en lugar de contemplarse? A) se va a tomar el té B) se queda en el pozo", "A) se va a tomar el té", "Es el giro del último verso."),
    E(f"{NAR} ¿Qué actitud tiene el hablante hacia el mito? A) humorística B) solemne", "A) humorística", "Termina con una acción cotidiana y simple."),
    E("Un poema de ejemplo tiene este epígrafe: «El que busca halla». ¿Cómo se llama esa frase al comienzo del poema? A) epígrafe B) estribillo", "A) epígrafe", "Es una frase breve colocada al comienzo.")],
   [E(f"{NAR} Una lectora dice: «El poema repite exactamente el sentido del mito». ¿Qué error comete? A) el poema invierte el mito: el hablante no se queda mirándose B) el poema no menciona el mito", "A) el poema invierte el mito: el hablante no se queda mirándose", "El poema transforma lo que se espera de Narciso."),
    E("Poema de ejemplo: «Subo la escalera de la torre, / como Ícaro, pero con las alas bien atadas». ¿Qué hace el poema con el mito de Ícaro? A) lo adapta: el hablante sube con precaución B) lo repite sin cambios", "A) lo adapta: el hablante sube con precaución", "Cambia el riesgo por el cuidado."),
    E("Un lector sin conocer a Narciso lee «Pozo» y entiende solo que alguien se mira en el agua. ¿Qué pierde? A) el sentido humorístico de invertir el mito B) la rima", "A) el sentido humorístico de invertir el mito", "Sin la referencia no se aprecia la inversión.")],
   [E("Pauta de revisión: ¿expliqué al menos dos recursos y su efecto? Un análisis nombra solo la rima. ¿Qué debe hacer? A) agregar otro recurso y explicar su efecto B) quitar la rima", "A) agregar otro recurso y explicar su efecto", "La pauta pide al menos dos recursos con efecto."),
    E("Poema de ejemplo: «Soy un Ulises sin barco, / y la casa me llama / desde el fondo del sueño». ¿A qué obra alude «Ulises»? A) a la Odisea, el viaje de regreso a casa B) a la Ilíada, la guerra de Troya", "A) a la Odisea, el viaje de regreso a casa", "Ulises (Odiseo) es el héroe del regreso, y el poema habla de una casa que llama.")],
   [E("Un estudiante comparó un poema con el mito de Prometeo sin decir qué aporta. ¿Qué falta? A) interpretar el sentido que la alusión añade B) más versos", "A) interpretar el sentido que la alusión añade", "Nombrar no basta."),
    E("Un lector escribe: «El poema “Pozo” reescribe un mito conocido». ¿Qué debe agregar para sostener la idea? A) cómo cambia el mito y una cita B) el nombre de la editorial", "A) cómo cambia el mito y una cita", "Se necesita evidencia y explicación.")],
   [E("Transfiere la pauta a este poema de ejemplo: «Sembré una semilla en la maceta, / la regué como a un secreto; / hoy asomó una hoja / y entendí que esperar era un verbo». ¿Qué recurso destaca en «regué como a un secreto»? A) una comparación B) una anáfora", "A) una comparación", "Une regar la semilla con cuidar un secreto mediante «como»."),
    E("En el mismo poema, ¿qué puede simbolizar la semilla? A) un proyecto o una esperanza que crece con paciencia B) un alimento", "A) un proyecto o una esperanza que crece con paciencia", "Esperar es el verbo central.")]),
  [E("Poema de ejemplo, con epígrafe: «Quien siembra vientos…» (refrán). Verso: «Yo sembré silencios, y ahora cosecho un eco». ¿Qué relación intertextual hay con el refrán? A) el poema lo transforma: cambia «vientos» por «silencios» y «tempestades» por «eco» B) lo copia entero", "A) el poema lo transforma: cambia «vientos» por «silencios» y «tempestades» por «eco»", "Reescribe el refrán con nuevas imágenes.")],
  [E("Transferir es... A) aplicar el método a un poema nuevo B) repetir el mismo poema", "A) aplicar el método a un poema nuevo", "La pauta sirve en otros textos."),
   E("Una alusión se interpreta explicando... A) qué hace el poema con la obra aludida B) cuántas veces se nombra", "A) qué hace el poema con la obra aludida", "Hay que interpretar su sentido."),
   E("Antes de entregar un análisis conviene... A) revisarlo con una pauta B) alargarlo", "A) revisarlo con una pauta", "Así se mejora.")],
  (f"Lee el poema de ejemplo: «{P1}» y escribe un comentario de 6 a 8 líneas con: el hablante y su actitud (con cita), un recurso de repetición o lenguaje figurado con su efecto, una relación entre forma y sentido y una posible alusión o relación con otra obra que conozcas (o indica que no encuentras ninguna). Revisa con la pauta y corrige una cosa.",
   "Hablante: un «yo» que se dirige a un «tú» ausente; actitud nostálgica y esperanzada: «ya vendrás, ya vendrás». La anáfora de «todavía» muestra apego. La personificación de la tarde, que «se sienta en tu lugar», hace sentir la ausencia. El verso libre da naturalidad, como una confesión en voz baja. No encuentro una alusión clara a otra obra. Revisión: agregué la cita que faltaba en la actitud.",
   ["identifica hablante y actitud con cita", "explica dos recursos", "relaciona forma y significado y revisa"], ["comentario de 6 a 8 líneas y una nota de revisión"], ["inventar alusiones", "recursos sin efecto"],
   "Marca cada parte de la pauta en tu comentario."),
  "Busca un refrán que conozcas y reescríbelo con otras imágenes.",
  "Escribe una pauta de revisión de cinco preguntas para el análisis de un poema.")
